import {commands} from './commands.js';
import {validate} from './validation.js';
export function generateScript(steps){const blocks=steps.map((step,i)=>{const action=commands.find(c=>c.id===step.actionId);if(!action)throw Error('Unsupported action.');if(Object.keys(validate(action,step.values)).length)throw Error(`Step ${i+1} has invalid parameters.`);return `# ${i+1}. ${action.name}\n# ${action.description}${action.risk==='modify'?'\n# CAUTION: Changes system state; review before running.':''}\n${action.generate(step.values)}`;});return `# Shellify | Turn your words into PowerShell.\n# Review before running. Target requirements are listed in the builder.\n# Compatible with Windows PowerShell 5.1 and PowerShell 7 on Windows.\n$ErrorActionPreference = 'Stop'\n\n${blocks.length?blocks.join('\n\n'):'# Add an action to start building your script.'}\n`;}
